svg.script:
  (() => {
    const button = document.getElementById('showAnswer');
    button.addEventListener('click', () => {
      const reveal = button.getAttribute('aria-pressed') !== 'true';
      button.setAttribute('aria-pressed', String(reveal));
      button.textContent = reveal ? 'HIDE ANSWER' : 'SHOW ANSWER';
      document.getElementById('answer3').classList.toggle('correct', reveal);
    });
  })();
  (function () {
  "use strict";

  const USER = "dowsy456";
  const PREFIX = "christianlumen";
  const BRANCH = "main";
  const FILE = "index.html";
  const CACHE_KEY = "gmm:lastCdnIndex:v6";
  const HTML_CACHE_KEY = "gmm:readyHtml:v6";
  const CACHE_KEYS = [CACHE_KEY, "gmm:lastCdnIndex:v5", "gmm:lastCdnIndex:v4", "gmm:lastCdnIndex:v3", "gmm:lastCdnIndex:v2", "gmm:lastCdnIndex"];
  // A verified hint, never a replacement for live repository discovery.
  const SEED_INDEX = 774;
  const DISCOVERY_TIMEOUT = 4000;
  const DOWNLOAD_TIMEOUT = 4500;
  const MAX_HTML_BYTES = 32 * 1024 * 1024;
  const mirrors = ["cdn.jsdelivr.net", "fastly.jsdelivr.net", "gcore.jsdelivr.net"];

  const button = document.getElementById("startBtnGroup");
  const buttonText = document.getElementById("startBtnText");
  const status = document.getElementById("statusText");
  const bar = document.getElementById("bar");
  const panel = document.getElementById("progressPanel");
  const track = document.getElementById("progressTrack");
  let state = { index: -1, current: 0, total: 0, complete: false };
  let child = null;
  let busy = false;
  let prepared = null;
  let workStarted = false;
  let discovering = false;
  let activeJobs = 0;
  let waiters = [];
  const candidateJobs = new Map();
  let failureMessage = null;
  let partialCandidates = [];
  const activeControllers = new Set();

  function renderProgress(targetDocument) {
    if (targetDocument === document && failureMessage) return;
    const label = targetDocument.getElementById("statusText");
    const progressBar = targetDocument.getElementById("bar");
    const progressTrack = targetDocument.getElementById("progressTrack");
    const name = PREFIX + (state.index >= 0 ? state.index : "");
    const numbers = state.current.toLocaleString() + (state.total ? " / " + state.total.toLocaleString() : "");
    if (label) label.textContent = name + " · " + numbers;
    if (progressBar) progressBar.style.width = state.complete ? "100%" : state.total ? Math.min(100, state.current / state.total * 100) + "%" : "36%";
    if (progressTrack) {
      progressTrack.classList.toggle("is-indeterminate", !state.total && !state.complete);
      progressTrack.setAttribute("aria-valuetext", name + ", " + numbers);
      if (state.complete || state.total) progressTrack.setAttribute("aria-valuenow", state.complete ? "100" : String(Math.round(state.current / state.total * 100)));
      else progressTrack.removeAttribute("aria-valuenow");
    }
  }

  function updateProgress(next) {
    state = Object.assign({}, state, next);
    renderProgress(document);
    try {
      if (child && !child.closed && child.document.getElementById("launcherLoading")) renderProgress(child.document);
    } catch (_) { /* The destination may have navigated after launch. */ }
  }

  function setBusy(value) {
    busy = value;
    button.disabled = value;
    button.setAttribute("aria-disabled", String(value));
    if (buttonText) buttonText.textContent = "Get More Math";
  }

  function cachedIndex() {
    let highest = -1;
    try {
      for (const key of CACHE_KEYS) {
        const value = localStorage.getItem(key);
        if (value === null || value === "") continue;
        const number = Number(value);
        if (Number.isSafeInteger(number) && number >= 0) highest = Math.max(highest, number);
      }
    } catch (_) { /* Local-file storage is optional. */ }
    return highest;
  }

  function cachedHTML() {
    try {
      const item = JSON.parse(localStorage.getItem(HTML_CACHE_KEY) || "null");
      if (!item || !Number.isSafeInteger(item.index) || item.index < 0 || typeof item.html !== "string" || item.html.length > 4 * 1024 * 1024) return null;
      if (!/<(?:!doctype\s+html|html|head|body)(?:\s|>)/i.test(item.html)) return null;
      if (!sources(item.index).includes(item.base)) return null;
      return { index: item.index, html: item.html, base: item.base, bytes: new TextEncoder().encode(item.html).byteLength };
    } catch (_) { return null; }
  }

  function remember(loaded) {
    try {
      localStorage.setItem(CACHE_KEY, String(loaded.index));
      // Store a working page, not just its index. A later click need not wait
      // for a rate-limited catalogue or an expired in-memory preparation.
      if (loaded.html.length <= 4 * 1024 * 1024) localStorage.setItem(HTML_CACHE_KEY, JSON.stringify(loaded));
    } catch (_) { /* Storage is optional for file URLs and private windows. */ }
  }

  function sources(index) {
    const path = "/gh/" + USER + "/" + PREFIX + index + "@" + BRANCH + "/" + FILE;
    return mirrors.map(function (host) { return "https://" + host + path; }).concat([
      "https://raw.githubusercontent.com/" + USER + "/" + PREFIX + index + "/" + BRANCH + "/" + FILE
    ]);
  }

  // The timeout covers headers AND the entire response body.
  async function request(url, options, timeout, consume, parentSignal) {
    const controller = new AbortController();
    activeControllers.add(controller);
    const abort = function () { controller.abort(); };
    if (parentSignal) {
      if (parentSignal.aborted) controller.abort();
      else parentSignal.addEventListener("abort", abort, { once: true });
    }
    const timer = setTimeout(abort, timeout);
    try {
      const response = await fetch(url, Object.assign({ cache: "default", credentials: "omit", referrerPolicy: "no-referrer" }, options, { signal: controller.signal }));
      if (!response.ok) {
        const error = new Error("Unavailable");
        error.status = response.status;
        throw error;
      }
      return await consume(response);
    } finally {
      clearTimeout(timer);
      if (parentSignal) parentSignal.removeEventListener("abort", abort);
      activeControllers.delete(controller);
    }
  }

  function indices(repositories) {
    return repositories.map(function (repo) {
      const match = repo && typeof repo.name === "string" && repo.name.match(/^christianlumen(\d+)$/);
      return match ? Number(match[1]) : -1;
    }).filter(function (index) { return Number.isSafeInteger(index) && index >= 0; });
  }

  function descending(values) {
    return Array.from(new Set(values)).sort(function (a, b) { return b - a; });
  }

  async function repositoryPage(page) {
    return request("https://api.github.com/users/" + USER + "/repos?per_page=100&page=" + page,
      {}, DISCOVERY_TIMEOUT, async function (response) {
        const repositories = await response.json();
        if (!Array.isArray(repositories)) throw new Error("Unavailable");
        const link = response.headers.get("Link") || "";
        const last = link.match(/[?&]page=(\d+)[^>]*>;\s*rel="last"/);
        const found = indices(repositories);
        partialCandidates.push.apply(partialCandidates, found);
        return { found: found, count: repositories.length, last: last ? Number(last[1]) : 0, next: /rel="next"/.test(link) };
      });
  }

  async function discover() {
    partialCandidates = [];
    const first = await repositoryPage(1);
    let found = first.found;
    let completed = 1;
    const last = first.last;
    if (last > 1) {
      // Six small metadata requests at a time; no thousands-of-URLs flood.
      let nextPage = 2;
      const workers = Array.from({ length: Math.min(6, last - 1) }, async function () {
        while (nextPage <= last) {
          const result = await repositoryPage(nextPage++);
          found.push.apply(found, result.found);
          completed++;
        }
      });
      const results = await Promise.allSettled(workers);
      if (results.some(function (result) { return result.status === "rejected"; })) throw new Error("Unavailable");
    } else if (first.next || first.count === 100) {
      // Link may be unavailable through a proxy; continue until a short page.
      let page = 2;
      while (true) {
        const result = await repositoryPage(page++);
        found.push.apply(found, result.found);
        completed++;
        if (result.count < 100) break;
      }
    }
    found = descending(found);
    if (!found.length) throw new Error("Unavailable");
    return found;
  }

  async function readHTML(response, report) {
    let html;
    let received = 0;
    if (response.body && response.body.getReader) {
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      const chunks = [];
      try {
        while (true) {
          const chunk = await reader.read();
          if (chunk.done) break;
          received += chunk.value.byteLength;
          if (received > MAX_HTML_BYTES) throw new Error("Unavailable");
          chunks.push(decoder.decode(chunk.value, { stream: true }));
          report(received);
        }
        chunks.push(decoder.decode());
        html = chunks.join("");
      } finally { reader.releaseLock(); }
    } else {
      html = await response.text();
      received = new TextEncoder().encode(html).byteLength;
      if (received > MAX_HTML_BYTES) throw new Error("Unavailable");
      report(received);
    }
    // Reject empty responses and CDN error messages before choosing a winner.
    if (!/<(?:!doctype\s+html|html|head|body)(?:\s|>)/i.test(html)) throw new Error("Unavailable");
    return { html: html, bytes: received };
  }

  async function loadIndex(index, signal, display) {
    const raceController = new AbortController();
    const abort = function () { raceController.abort(); };
    if (signal) {
      if (signal.aborted) raceController.abort();
      else signal.addEventListener("abort", abort, { once: true });
    }
    let largestBody = 0;
    const report = function (bytes) {
      largestBody = Math.max(largestBody, bytes);
      if (display()) updateProgress({ index: index, current: largestBody, total: 0, complete: false });
    };
    try {
      const downloads = sources(index).map(function (url) {
        return request(url, {}, DOWNLOAD_TIMEOUT, async function (response) {
          const body = await readHTML(response, report);
          return { index: index, html: body.html, bytes: body.bytes, base: url };
        }, raceController.signal);
      });
      const result = await Promise.any(downloads);
      const hasRelativeAssets = /<(?:script|link|img|source|video|audio|iframe)\b[^>]*\b(?:src|href)\s*=\s*["'](?![a-z][a-z\d+.-]*:|\/\/|#)/i.test(result.html);
      const hasAbsoluteBase = /<base\b[^>]*href\s*=\s*["'](?:https?:\/\/|\/\/)/i.test(result.html);
      if (new URL(result.base).hostname === "raw.githubusercontent.com" && hasRelativeAssets && !hasAbsoluteBase) {
        // Raw is useful for HTML but its nosniff text/plain assets cannot run.
        // The already-running CDN race supplies a verified working asset host.
        const assetSource = await Promise.any(downloads.slice(0, mirrors.length));
        result.base = assetSource.base;
      }
      return result;
    } finally {
      // Cancel unused transports only after a complete valid HTML body wins.
      raceController.abort();
      if (signal) signal.removeEventListener("abort", abort);
    }
  }

  function notifyWaiters() {
    if (prepared) {
      const listeners = waiters;
      waiters = [];
      listeners.forEach(function (listener) { listener.resolve(prepared); });
    } else if (!discovering && activeJobs === 0) {
      const listeners = waiters;
      waiters = [];
      listeners.forEach(function (listener) { listener.reject(new Error("Unavailable")); });
    }
  }

  function accept(loaded, persist) {
    // Keep the newest fully downloaded result available. An unfinished newer
    // request never blocks use of the last working page.
    if (!prepared || loaded.index >= prepared.index) {
      prepared = loaded;
      if (persist) remember(loaded);
      updateProgress({ index: loaded.index, current: loaded.bytes, total: loaded.bytes, complete: true });
    }
    notifyWaiters();
  }

  function startCandidate(index) {
    if (!Number.isSafeInteger(index) || index < 0 || candidateJobs.has(index)) return;
    activeJobs++;
    const job = loadIndex(index, null, function () { return !prepared && (state.index < 0 || index >= state.index); })
      .then(function (loaded) { accept(loaded, true); })
      .catch(function () { /* Other mirrors, the cached page, or discovery may succeed. */ })
      .finally(function () { activeJobs--; notifyWaiters(); });
    candidateJobs.set(index, job);
  }

  function beginPreparation() {
    if (!workStarted) {
      workStarted = true;
      discovering = true;
      const cached = cachedHTML();
      if (cached) accept(cached, false);
      // Begin real GETs immediately. Never wait for catalogue metadata, issue
      // HEAD probes, or enumerate nonexistent numbered repositories.
      const hint = cachedIndex();
      if (hint >= 0) startCandidate(hint);
      startCandidate(SEED_INDEX);
      discover().then(function (found) {
        // Refresh in the background; promote a newer page once fully ready.
        found.slice(0, 3).forEach(startCandidate);
      }).catch(function () {
        // A rate limit does not trigger any bulk scan or delay a working page.
      }).finally(function () { discovering = false; notifyWaiters(); });
    }
    if (prepared) return Promise.resolve(prepared);
    if (!discovering && activeJobs === 0) return Promise.reject(new Error("Unavailable"));
    return new Promise(function (resolve, reject) { waiters.push({ resolve: resolve, reject: reject }); });
  }

  function writeDocument(tab, html, onReady, onLeave) {
    // document.open() uses its caller's document URL. Run the writer in the
    // destination realm so about:blank does not become the SVG's file URL.
    // HTML is passed as data, never interpolated into this fixed function body.
    const write = tab.Function("html", "ready", "leave", "resolve", "reject", "try { document.open(); if (ready) document.addEventListener('DOMContentLoaded', ready, { once: true }); if (leave) window.addEventListener('pagehide', leave, { once: true }); document.write(html); document.close(); resolve(); } catch (error) { reject(error); }");
    return new Promise(function (resolve, reject) {
      // A destination-owned event-loop task is essential: calling the writer
      // on the source stack would still make the source the entry document.
      // Microtask handoff preserves about:blank without a timed delay.
      const run = tab.Function("write", "html", "ready", "leave", "resolve", "reject", "queueMicrotask(function () { write(html, ready, leave, resolve, reject); });");
      run(write, html, onReady || null, onLeave || null, resolve, reject);
    });
  }

  async function loadingPage(tab) {
    await writeDocument(tab, '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Get More Math</title><style>html,body{height:100%;margin:0}body{background:#f8f8f8;color:#555;font:16px Arial,sans-serif;display:grid;place-items:center}.box{width:min(360px,80vw);text-align:center}.brand{font:bold 66px Georgia,serif;letter-spacing:-6px;color:#479b45;margin-bottom:32px}#statusText{font-variant-numeric:tabular-nums;margin-bottom:16px}#progressTrack{height:6px;background:#e4e4e4;overflow:hidden;border-radius:3px}#bar{height:100%;background:#479b45;width:0}.is-indeterminate #bar{animation:load 1.1s ease-in-out infinite alternate}@keyframes load{to{transform:translateX(177%)}}@media(prefers-reduced-motion:reduce){.is-indeterminate #bar{animation:none}}</style></head><body><main class="box" id="launcherLoading"><div class="brand">gmm</div><div id="statusText" role="status" aria-live="polite">christianlumen · 0</div><div id="progressTrack" role="progressbar" aria-label="christianlumen" aria-valuemin="0" aria-valuemax="100"><div id="bar"></div></div></main></body></html>');
    renderProgress(tab.document);
  }

  function withBase(loaded) {
    // Raw hosts serve scripts/styles as text/plain with nosniff. Resolve those
    // assets through the CDN when the raw HTML transport wins the race.
    const assetURL = new URL(loaded.base).hostname === "raw.githubusercontent.com" ? sources(loaded.index)[0] : loaded.base;
    const base = new URL(".", assetURL).href.replace(/&/g, "&amp;").replace(/"/g, "&quot;");
    let html = loaded.html.replace(/http:\/\/cdn\.jsdelivr\.(?:net|com)\//gi, "https://cdn.jsdelivr.net/");
    // Respect an existing base; otherwise preserve the source's relative assets.
    if (/<base\b[^>]*href\s*=/i.test(html)) return html;
    const tag = '<base href="' + base + '">';
    if (/<head\b[^>]*>/i.test(html)) return html.replace(/<head\b[^>]*>/i, function (head) { return head + tag; });
    if (/<html\b[^>]*>/i.test(html)) return html.replace(/<html\b[^>]*>/i, function (root) { return root + "<head>" + tag + "</head>"; });
    return "<head>" + tag + "</head>" + html;
  }

  async function launch(loaded, tab) {
    if (tab.closed) throw new Error("closed");
    const html = withBase(loaded);
    // Loaded applications do not need access to the launcher window.
    try { tab.opener = null; } catch (_) {}
    let handedOff = false;
    await writeDocument(tab, html, function () {
      handedOff = true;
      updateProgress({ index: loaded.index, current: loaded.bytes, total: loaded.bytes, complete: true });
      setBusy(false);
      // No delay or history tricks. The browser decides whether this tab is closable.
      try { tab.focus(); } catch (_) {}
      try { window.close(); } catch (_) {}
    }, function () {
      // Closing a destination with still-loading deferred scripts must not
      // leave the source button disabled forever.
      queueMicrotask(function () {
        if (!handedOff && tab.closed) fail("Tab closed. Try again.");
      });
    });
  }

  function fail(message) {
    failureMessage = message;
    if (panel) panel.hidden = false;
    status.textContent = message;
    if (bar) bar.style.width = "0%";
    if (track) { track.classList.remove("is-indeterminate"); track.removeAttribute("aria-valuenow"); }
    try {
      if (child && !child.closed && child.document.getElementById("launcherLoading")) {
        child.document.getElementById("statusText").textContent = message;
        child.document.getElementById("progressTrack").hidden = true;
      }
    } catch (_) {}
    setBusy(false);
  }

  async function handleClick() {
    if (busy) return;
    failureMessage = null;
    setBusy(true);
    if (panel) panel.hidden = false;
    // Keep this synchronous with the user's click so popup permission is retained.
    child = window.open("about:blank", "_blank");
    if (!child) { fail("Allow pop-ups, then try again."); return; }
    const destination = child;
    try {
      await loadingPage(destination);
      if (!prepared && !discovering && activeJobs === 0) { workStarted = false; candidateJobs.clear(); }
      const loaded = prepared || await beginPreparation();
      await launch(loaded, destination);
    } catch (error) {
      fail(error && error.message === "closed" ? "Tab closed. Try again." : "Unable to load. Check your connection and try again.");
    }
  }

  button.addEventListener("click", handleClick);
  // Native XHTML buttons already support Enter and Space without double activation.
  if (button.localName !== "button") {
    button.setAttribute("role", "button");
    button.setAttribute("tabindex", "0");
    button.addEventListener("keydown", function (event) {
      if (event.key === "Enter" || event.key === " ") { event.preventDefault(); handleClick(); }
    });
  }
  window.addEventListener("pagehide", function () {
    activeControllers.forEach(function (controller) { controller.abort(); });
  });
  beginPreparation().catch(function () { /* A click can retry if the background fetch failed. */ });
})();
